package com.weatherhub.operations.dto; import com.weatherhub.operations.OpsEvent; import java.time.LocalDateTime;
public record OpsEventVO(Long id,String sourceType,String sourceKey,String level,String status,String title,String content,String regionName,Double longitude,Double latitude,LocalDateTime occurredAt,LocalDateTime createdAt) { public static OpsEventVO from(OpsEvent e) { return new OpsEventVO(e.getId(),e.getSourceType(),e.getSourceKey(),e.getLevel(),e.getStatus(),e.getTitle(),e.getContent(),e.getRegionName(),e.getLongitude(),e.getLatitude(),e.getOccurredAt(),e.getCreatedAt()); } }
